# Final plot to show improvement in test log loss over the baseline
# The code for the plot was modified from code generated by Claude Opus 5.5
import matplotlib.pyplot as plt
import numpy as np
import pandas as pd

final_data = pd.read_csv("results/metrics/final_comparison.csv")
baseline_loss = final_data.loc[final_data["model"] == "baseline", "log_loss"].iloc[0]

models = final_data[final_data["model"] != "baseline"].copy()
models["improvement"] = baseline_loss - models["log_loss"]  # positive = better than baseline

model_names = {"hgb": "Gradient boosting", "rf": "Random forest", "logreg": "Logistic regression"}
model_colors = {"hgb": "#2b6cb0", "rf": "#38a169", "logreg": "#dd8452"}

# Order model types by their context improvement, best at the top
order = (models[models["features"] == "context"]
         .sort_values("improvement", ascending=True)["model"].tolist())

fig, ax = plt.subplots(figsize=(8, 4.2))
height = 0.38
y = np.arange(len(order))

for i, model in enumerate(order):
    pitch = models[(models["model"] == model) & (models["features"] == "pitch")]["improvement"].iloc[0]
    context = models[(models["model"] == model) & (models["features"] == "context")]["improvement"].iloc[0]
    color = model_colors[model]
    ax.barh(i - height / 2, pitch, height, color=color, alpha=0.55)
    ax.barh(i + height / 2, context, height, color=color)
    ax.text(pitch + 0.002, i - height / 2, f"{pitch:.4f}  pitch only", va="center", fontsize=9)
    ax.text(context + 0.002, i + height / 2, f"{context:.4f}  pitch + context", va="center", fontsize=9)

ax.set_yticks(y, [model_names[m] for m in order])
ax.set_xlim(0, models["improvement"].max() * 1.35)
ax.set_xlabel(f"Reduction in test log loss vs. baseline (baseline = {baseline_loss:.4f})")
ax.set_title("Improvement over the baseline model (September 2026 test set)")

fig.tight_layout()
fig.savefig("results/figures/improvement_over_baseline.png", dpi=200)